// import React from 'react';
import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { Link } from 'react-router-dom';

import Sidebar from '../About/Sidebar';

export default function AddCommission() {
  const [name, setName] = useState('');
  const [errorMessage, setErrorMessage] = useState('');
  const [successMessage, setSuccessMessage] = useState('');

  const handleSubmit = async (event) => {
    event.preventDefault();
    try {
      const response = await axios.post('http://localhost:5000/commission', {
        name: name
      });
      setSuccessMessage(response.data.message);
      setName(''); // Clear the input field after successful submission
    } catch (error) {
      if (error.response) {
        setErrorMessage(error.response.data.error);
      } else {
        setErrorMessage('An error occurred. Please try again later.');
      }
    }
  };
  return (

    <div className="wrapper">
      <nav className="main-header navbar navbar-expand navbar-white navbar-light">
        <ul className="navbar-nav">
          <li className="nav-item">
            <a className="nav-link" data-widget="pushmenu" href="#" role="button"><i className="fas fa-bars"></i></a>
          </li>
        </ul>
      </nav>

      {/* sidebar menu */}
      <aside className="main-sidebar sidebar-dark-primary elevation-4">
        {/* <!-- Brand Logo --> */}
        <a href="index3.html" className="brand-link">
          <img src="dist/img/AdminLTELogo.png" alt="AdminLTE Logo" className="brand-image img-circle elevation-3" style={{ opacity: '.8' }} />
          <span className="brand-text font-weight-light">AdminLTE 3</span>
        </a>

        {/* <!-- Sidebar --> */}
        <div className="sidebar">
          {/* <!-- Sidebar user panel (optional) --> */}
          <div className="user-panel mt-3 pb-3 mb-3 d-flex">
            <div className="image">
              <img src="dist/img/user2-160x160.jpg" className="img-circle elevation-2" alt="User Image" />
            </div>
            <div className="info">
              <a href="#" className="d-block">Alexander Pierce</a>
            </div>
          </div>

          {/* <!-- SidebarSearch Form --> */}
          <div className="form-inline">
            <div className="input-group" data-widget="sidebar-search">
              <input className="form-control form-control-sidebar" type="search" placeholder="Search" aria-label="Search" />
              <div className="input-group-append">
                <button className="btn btn-sidebar">
                  <i className="fas fa-search fa-fw"></i>
                </button>
              </div>
            </div>
          </div>

          {/* <!-- Sidebar Menu --> */}
          <nav className="mt-2">
            <Sidebar />
          </nav>
        </div>
      </aside>

      {/* Content goes to hare */}
      <div className="content-wrapper">
        <section className="content">
          {/* <div className="container-fluid"> */}
          {/* content goes to hare  */}

          <div className="container mt-3">
            <div className="card card-default">
              <div className="card-header">
                <h3 className="card-title mt-3">Commission Type</h3>
                <div className="card-tools">
                  {/* <a href="/commission" className="btn btn-sm btn-success"> All </a> */}
                  <Link to="/commission" className="btn btn-sm btn-success">All</Link>
                </div>
              </div>

              <div className="form-Container m-3">
                {/* <form onSubmit={handleSubmit}>
                  <div className="row">
                    <div className="col-6 d-flex flex-column  mb-2">
                      <label for="">Name:<span className="required">*</span></label>
                      <input className="form-control" type="text" name="name" placeholder="Enter Name" />
                      <span style={{ fontSize: '12px' }}>(Commission Type (CPA, CPL, CPI, CPS, RevShare, etc))</span>
                    </div>
                  </div>

                  <div className="row mt-3">
                    <div className="col-6">
                      <input type="submit" className="btn btn-success btn-md" name="submit" value="submit" />
                    </div>
                  </div>
                </form> */}
                <form onSubmit={handleSubmit}>
                  <div className="row">
                    <div className="col-6 d-flex flex-column  mb-2">
                      <label htmlFor="name">Name:<span className="required">*</span></label>
                      <input
                        className="form-control"
                        type="text"
                        id="name"
                        name="name"
                        value={name}
                        onChange={(e) => setName(e.target.value)}
                        placeholder="Enter Name"
                      />
                      <span style={{ fontSize: '12px' }}>(Commission Type (CPA, CPL, CPI, CPS, RevShare, etc))</span>
                    </div>
                  </div>
                  <div className="row mt-3">
                    <div className="col-6">
                      <input type="submit" className="btn btn-success btn-md" name="submit" value="submit" />
                    </div>
                  </div>
                </form>

              </div>
            </div>
          </div>



          {/* </div> */}
        </section>
      </div>
    </div>
  )
}
